create table public.consensus_snapshots(id uuid primary key default gen_random_uuid(),consensus_key text not null unique,asset_id uuid not null references public.assets(id),horizon text not null,cutoff_at timestamptz not null,available_at timestamptz not null,consensus_policy_version text not null,correlation_version text not null,result text not null,confidence integer,conflict_level text not null,critical_veto_agent text,raw_agent_count integer not null,known_agent_count integer not null,independent_evidence_groups integer not null,data_quality integer,input_analysis_ids jsonb not null,evidence_group_ids jsonb not null,result_hash text not null,created_at timestamptz not null default now());
create table public.consensus_opinions(id uuid primary key default gen_random_uuid(),consensus_id uuid not null references public.consensus_snapshots(id),input_id text not null,agent_id text not null,agent_version text not null,stance text not null check(stance in('BULLISH','BEARISH','NEUTRAL','UNKNOWN')),strength integer,confidence integer,data_quality integer,evidence_refs jsonb not null,knowledge_refs jsonb not null,evidence_families jsonb not null,critical_veto boolean not null,unique(consensus_id,input_id));create table public.consensus_evidence_overlaps(id uuid primary key default gen_random_uuid(),consensus_id uuid not null references public.consensus_snapshots(id),left_input_id text not null,right_input_id text not null,overlap_level text not null check(overlap_level in('LOW','MEDIUM','HIGH')),shared_families jsonb not null,shared_refs jsonb not null,unique(consensus_id,left_input_id,right_input_id));
create or replace function public.prevent_consensus_mutation()returns trigger language plpgsql as $$begin raise exception'Consensus history is immutable';end$$;create trigger consensus_snapshots_immutable before update or delete on public.consensus_snapshots for each row execute function public.prevent_consensus_mutation();create trigger consensus_opinions_immutable before update or delete on public.consensus_opinions for each row execute function public.prevent_consensus_mutation();create trigger consensus_overlaps_immutable before update or delete on public.consensus_evidence_overlaps for each row execute function public.prevent_consensus_mutation();alter table public.consensus_snapshots enable row level security;alter table public.consensus_opinions enable row level security;alter table public.consensus_evidence_overlaps enable row level security;create policy "public read consensus snapshots" on public.consensus_snapshots for select using(true);create policy "public read consensus opinions" on public.consensus_opinions for select using(true);create policy "public read consensus overlaps" on public.consensus_evidence_overlaps for select using(true);grant select on public.consensus_snapshots,public.consensus_opinions,public.consensus_evidence_overlaps to anon,authenticated;grant all on public.consensus_snapshots,public.consensus_opinions,public.consensus_evidence_overlaps to service_role;
alter table public.scheduled_jobs drop constraint if exists scheduled_jobs_job_type_check;alter table public.scheduled_jobs add constraint scheduled_jobs_job_type_check check(job_type in('BASELINE_FORECAST','FORECAST_OUTCOME','FORECAST_PERFORMANCE','NEWS_INGESTION','CATALYST_CLASSIFICATION','CONSENSUS'));insert into public.scheduled_jobs(job_key,job_type,scheduler_version,interval_seconds,lease_seconds,status,next_run_at,rate_limit_budget)values('consensus-5m','CONSENSUS','forecast-scheduler-v1.3',300,240,'HEALTHY',now(),'{}')on conflict(job_key)do nothing;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx','qualification','data_gap_closure','simulation','historical_replay','forecast_catalyst','expert_knowledge','baseline_forecast','forecast_performance','forecast_scheduler','forecast_outcomes','specialist_agents','news_ingestion','catalyst_classification','consensus'));
